/* eslint-disable @stencil-community/required-jsdoc */
import { Component, h, Element, Host, Prop, ComponentInterface, State, Watch } from '@stencil/core';
import { t } from '@src/shared/i18n';
import {
  SingleValueType,
  CascaderDataNode,
  CascaderSearchNode,
  CascaderColumnPartProps,
  CascaderMultipleConfig,
  CascaderColumnSelectAllContext,
} from '../types';
import { Value } from '@src/components/ks-menu-item/types';
import { isLeaf, noop, toPathKey, toPathKeys, toPathOptions } from '../utils';
import { commonMessages } from '@fe-infra/keystone-locales';
import { Consume } from '@src/framework/runtime-context';
import { CascaderContext, CascaderContextValue } from '../context';
import { EMPTY_ARRAY } from '@src/shared/vdom/empty-constants';

const prefix = 'cascader-panel__columns';

@Component({
  tag: 'ks-cascader-panel-list',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCascaderPanelList implements ComponentInterface {
  @Element() el!: HTMLKsCascaderPanelListElement;

  @Prop() multiple!: boolean;
  @Prop() columnSelectAll?: CascaderMultipleConfig['columnSelectAll'];
  @Prop() searchValue!: string;
  @Prop() toggleOpen: (open?: boolean) => void = noop;
  @Prop() open?: boolean;
  @Prop() disabled?: boolean;

  @Prop() options!: CascaderDataNode[];
  @Prop() values: SingleValueType[] = [];
  @Prop() halfValues: SingleValueType[] = [];
  @Prop() key2CheckedChildrenCount: Map<Value, number> = new Map();
  @Prop() changeOnSelect?: boolean;
  @Prop() onSelect!: (valuePath: SingleValueType, originalChecked: boolean) => void;
  @Prop() onSelectAll?: (valuePaths: SingleValueType[], checked: boolean) => void;
  @Prop() searchOptions!: CascaderSearchNode[];
  @Prop() loadData?: (selectOptions: CascaderDataNode[]) => Promise<void> | void;
  @Prop() loadedKeys?: Value[][];
  @Prop() onLoadData!: (newLoadedKeys: Value[][]) => void;

  @Prop() columnProps: CascaderColumnPartProps | CascaderColumnPartProps[] = [];

  @Prop() virtual?:
    | boolean
    | { estimatedItemHeight: number | ((item: CascaderDataNode | CascaderSearchNode) => number) };

  @State() loadingKeys: Value[] = [];
  private internalLoadedKeysList: Value[][] = [];
  private internalLoadData = async (valueCells: Value[]) => {
    if (!this.loadData || this.searchValue) {
      return;
    }

    const pathKey = toPathKey(valueCells);

    if (toPathKeys(this.internalLoadedKeysList).includes(pathKey)) {
      return;
    }

    const optionList = toPathOptions(valueCells, this.options);
    const rawOptions = optionList.map((item) => item.option);
    const lastOption = rawOptions[rawOptions.length - 1];

    if (lastOption && !isLeaf(lastOption)) {
      this.loadingKeys = [...this.loadingKeys, pathKey];

      try {
        await this.loadData(rawOptions);

        const nextLoadedKeysList = [...this.internalLoadedKeysList, valueCells];
        if (this.loadedKeys === undefined) {
          this.internalLoadedKeysList = nextLoadedKeysList;
        }
        this.onLoadData(nextLoadedKeysList);
      } catch (e) {
        // TODO: Process error
        console.error('KsCascaderPanelList onLoadData error:', e);
        throw e;
      } finally {
        this.loadingKeys = this.loadingKeys.filter((key) => key !== pathKey);
      }
    }
  };
  @Watch('loadedKeys')
  onLoadedKeysChange(newLoadedKeys: Value[][]) {
    this.internalLoadedKeysList = newLoadedKeys;
  }

  @State() activeValueCells: Value[] = [];

  private onPathOpen = (nextValueCells: Value[]) => {
    this.activeValueCells = nextValueCells;

    this.internalLoadData(nextValueCells);
  };

  private onPathSelect = (valuePath: SingleValueType, leaf: boolean, originalChecked: boolean) => {
    this.onSelect(valuePath, originalChecked);

    if (!this.multiple && leaf) {
      this.toggleOpen(false);
    }
  };

  private onColumnSelectAll = (valuePaths: SingleValueType[], checked: boolean) => {
    this.onSelectAll?.(valuePaths, checked);
  };

  private isSelectable = (option: CascaderDataNode | CascaderSearchNode) => {
    if (this.disabled) {
      return false;
    }

    const { disabled: optionDisabled } = option;
    const isMergedLeaf = isLeaf(option);

    return !optionDisabled && (isMergedLeaf || this.changeOnSelect || this.multiple);
  };

  private optionColumns: CascaderDataNode[][] | CascaderSearchNode[][] = [];
  @Watch('options')
  @Watch('activeValueCells')
  generateOptionColumnsForRender() {
    const optionList = [];
    // should render option list
    optionList.push(this.options);
    let currentList = this.options;
    for (const valueCell of this.activeValueCells) {
      const currentOption = currentList.find((item) => item.value === valueCell);
      const subOptions = currentOption?.children;
      if (!subOptions?.length) {
        break;
      }
      currentList = subOptions;
      optionList.push(subOptions);
    }
    this.optionColumns = optionList;
  }

  @Watch('open')
  prepareActiveCellsForRender() {
    // We need to reset activeValueCells when open && this is a single select.
    if (!this.multiple) {
      this.activeValueCells = this.values[0] || [];
    }
  }

  private renderEmptyList() {
    return (
      <slot name="empty">
        <ks-empty-state class={`${prefix}__empty`} size="sm" title={t(commonMessages.empty)} />
      </slot>
    );
  }

  private getColumnSelectAllConfig(context: CascaderColumnSelectAllContext) {
    const columnSelectAll = this.columnSelectAll;
    if (!this.multiple || !columnSelectAll) {
      return undefined;
    }

    if (columnSelectAll === true) {
      return true;
    }

    const { show = true } = columnSelectAll;
    const visible = typeof show === 'function' ? show(context) : show;
    return visible ? columnSelectAll : undefined;
  }

  private renderColumns() {
    const columnProps = {
      multiple: this.multiple,
      onSelect: this.onPathSelect,
      onActive: this.onPathOpen,
      onToggleOpen: this.toggleOpen,
      checkedSet: new Set(toPathKeys(this.values)),
      halfCheckedSet: new Set(toPathKeys(this.halfValues)),
      key2CheckedChildrenCount: this.key2CheckedChildrenCount,
      loadingKeys: this.loadingKeys,
      isSelectable: this.isSelectable,
      virtual: this.virtual,
    };

    const loading =
      this.loadingKeys.includes(toPathKey(this.activeValueCells)) &&
      this.activeValueCells.length === this.optionColumns.length;

    const columns = this.optionColumns.map((col, index) => {
      const prevValuePath = this.activeValueCells.slice(0, index);
      const activeValue = this.activeValueCells[index];
      const columnSelectAllContext = {
        index,
        options: col as CascaderDataNode[],
        prevValuePath,
      };

      return (
        <ks-cascader-panel-column
          key={index}
          index={index}
          lastColumn={!loading && index === this.optionColumns.length - 1}
          {...columnProps}
          options={col}
          prevValuePath={prevValuePath}
          activeValue={activeValue}
          columnSelectAll={this.getColumnSelectAllConfig(columnSelectAllContext)}
          onSelectAll={this.onColumnSelectAll}
          {...(Array.isArray(this.columnProps) ? this.columnProps[index] || [] : this.columnProps)}
        >
          {this.contextFromCascader?.getPassThroughSlotsFnArr[index]?.()}
        </ks-cascader-panel-column>
      );
    });
    if (loading) {
      columns.push(
        <ks-cascader-panel-column
          key={columns.length}
          index={columns.length}
          lastColumn
          {...columnProps}
          options={EMPTY_ARRAY}
          prevValuePath={this.activeValueCells}
          {...(Array.isArray(this.columnProps) ? this.columnProps[0] || [] : this.columnProps)}
        />,
      );
    }
    return columns;
  }

  private renderSearchColumns() {
    const columnProps = {
      multiple: this.multiple,
      onSelect: this.onPathSelect,
      onActive: this.onPathOpen,
      onToggleOpen: this.toggleOpen,
      checkedSet: new Set(toPathKeys(this.values)),
      halfCheckedSet: new Set(toPathKeys(this.halfValues)),
      key2CheckedChildrenCount: this.key2CheckedChildrenCount,
      loadingKeys: this.loadingKeys,
      isSelectable: this.isSelectable,
      virtual: this.virtual,
    };

    return (
      <ks-cascader-panel-column
        key={0}
        index={'search'}
        lastColumn
        {...columnProps}
        options={this.searchOptions}
        prevValuePath={EMPTY_ARRAY}
        activeValue={''}
        {...(Array.isArray(this.columnProps) ? this.columnProps[0] || [] : this.columnProps)}
      >
        {this.contextFromCascader?.getPassThroughSlotsFnArr[0]?.()}
      </ks-cascader-panel-column>
    );
  }

  render() {
    const isEmpty = !this.optionColumns[0]?.length || (!!this.searchValue && !this.searchOptions.length);
    return (
      <Host class="KsCascaderPanelList">
        <div
          class={{
            [prefix]: true,
            [`${prefix}--empty`]: isEmpty,
          }}
        >
          {isEmpty && this.renderEmptyList()}
          {!isEmpty && !this.searchValue && this.renderColumns()}
          {!isEmpty && this.searchValue && this.renderSearchColumns()}
        </div>
      </Host>
    );
  }

  componentWillLoad() {
    this.generateOptionColumnsForRender();
  }

  @Consume({
    context: CascaderContext,
    subscribe: true,
  })
  @State()
  contextFromCascader?: CascaderContextValue;
}
