import { Value } from '@src/components/ks-menu-item/types';
import { DataEntity } from '@src/components/ks-tree-view/utils';
import { ShowCheckedStrategy, SingleValueType, CascaderDataNode } from '../types';
import { toPathKey } from './common';

export function formatStrategyValues(
  pathKeys: Value[],
  pathKeyEntities: Record<string, DataEntity<CascaderDataNode>>,
  showCheckedStrategy?: ShowCheckedStrategy,
) {
  if (showCheckedStrategy === 'all') {
    return pathKeys;
  }

  const valueSet = new Set(pathKeys);

  return pathKeys.filter((key) => {
    const entity = pathKeyEntities[key];
    const parent = entity?.parent || null;
    const children = entity?.children || null;

    if (entity && entity.node.disabled) {
      return true;
    }

    return showCheckedStrategy === 'child'
      ? !(children && children.some((child) => child.key && valueSet.has(child.key)))
      : !(parent && !parent.node.disabled && valueSet.has(parent.key));
  });
}

/**
 * Convert path keys to path options
 * @param pathKey Path value array
 * @param options Tree node array
 * @param stringMode Whether in string mode
 * @returns
 */
export function toPathOptions(
  pathKey: SingleValueType,
  options: CascaderDataNode[],
  //
  stringMode = false,
) {
  let currentList = options;
  const valueOptions: {
    value: SingleValueType[number];
    index: number;
    option: CascaderDataNode;
  }[] = [];

  for (let i = 0; i < pathKey.length; i++) {
    const value = pathKey[i]!;
    const index = currentList.findIndex((item) =>
      stringMode ? String(item.value) === String(value) : item.value === value,
    );
    const foundOption = index !== -1 ? currentList[index] : null;
    valueOptions.push({
      value: foundOption?.value || value,
      index,
      option: foundOption as CascaderDataNode,
    });
    currentList = foundOption?.children || [];
  }
  return valueOptions;
}

export function getKey(entity: DataEntity<CascaderDataNode>) {
  return toPathKey(entity.nodes.map((node) => node.value));
}
